}

export function createLog(limit: number) {
  let lines: string[] = []

  return {
    add(text: string): void {
      lines = [sentence(text), ...lines].slice(0, limit)
    },
    lines(): readonly string[] {
      return lines
    },
  }
}

export type ActivityLog = ReturnType<typeof createLog>

